const fs=require('fs'),cp=require('child_process');
const {chromium}=require('@playwright/test');
const TARGET='assets/css/components/cards/service-card-home-hero-feed.css';
const IMPORTER='assets/css/pages/home-runtime-feed.css';
const PAGE='index.html';
const FEED_RUNTIME='assets/js/pages/home/public-services.js';
const CARD_RUNTIME='assets/js/components/public-service-card.js';
const FIXTURE='ux052-r2-fixture.html';
const SHA=process.env.TARGET_SHA,TARGET_BLOB=process.env.TARGET_BLOB,IMPORTER_BLOB=process.env.IMPORTER_BLOB,PAGE_BLOB=process.env.PAGE_BLOB,FEED_BLOB=process.env.FEED_BLOB,CARD_BLOB=process.env.CARD_BLOB;
const VIEWPORTS=[359,389,390,391,430,559,560,561,1024];
const AVATAR_SEL='html.home-index-root body.home-index-shell .service-card__avatar';
const TAGS_SEL='html.home-index-root body.home-index-shell .service-card__tags';
const sh=c=>cp.execSync(c,{encoding:'utf8',stdio:['ignore','pipe','pipe']}).trim();
const assert=(x,m)=>{if(!x)throw new Error(m)};
function parse(src){const lines=src.split(/\r?\n/);let depth=0,sp=[],ap=[],sel=null;const ds=[],stack=[],re=/^\s*([\w-]+)\s*:\s*(.*?)\s*;\s*$/,norm=p=>p.join(' ').replace(/\{\s*$/,'').replace(/\s+/g,' ').trim();for(let i=0;i<lines.length;i++){const line=lines[i],t=line.trim(),o=(line.match(/\{/g)||[]).length,c=(line.match(/\}/g)||[]).length;if(!sel){if(ap.length){if(t)ap.push(t);if(line.includes('{')){stack.push({type:'at',header:norm(ap),depthBefore:depth});ap=[]}}else if(t.startsWith('@')&&!t.includes(';')){if(line.includes('{'))stack.push({type:'at',header:norm([t]),depthBefore:depth});else ap=[t]}else if(sp.length){if(t)sp.push(t);if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}else if(t&&!t.startsWith('/*')&&!t.startsWith('*')&&t!=='*/'&&t!=='}'&&!t.startsWith('@')&&!line.includes(';')){sp=[t];if(line.includes('{')){sel=norm(sp);sp=[];stack.push({type:'rule',selector:sel,depthBefore:depth})}}}if(sel){const m=line.match(re);if(m){const raw=m[2].trim(),important=/\s*!important\s*$/i.test(raw),context=stack.filter(x=>x.type==='at').map(x=>x.header).join(' || ');ds.push({line:i+1,selector:sel,property:m[1].toLowerCase(),value:raw,important,context})}}depth+=o-c;while(stack.length&&depth<=stack.at(-1).depthBefore){const p=stack.pop();if(p.type==='rule')sel=null}}const last=new Map(),dead=[];for(let i=ds.length-1;i>=0;i--){const d=ds[i],k=`${d.context} >>> ${d.selector} >>> ${d.property}`,l=last.get(k);if(l&&(!d.important||l.important))dead.push({...d,winnerLine:l.line,winnerValue:l.value,winnerImportant:l.important});if(!l||d.important||!l.important)last.set(k,d)}return{declarations:ds,dead:dead.sort((a,b)=>a.line-b.line)}}
function guard(){assert(sh('git rev-parse HEAD')===SHA,'wrong SHA');assert(sh(`git hash-object ${TARGET}`)===TARGET_BLOB,'target blob drift');assert(sh(`git hash-object ${IMPORTER}`)===IMPORTER_BLOB,'importer blob drift');assert(sh(`git hash-object ${PAGE}`)===PAGE_BLOB,'page blob drift');assert(sh(`git hash-object ${FEED_RUNTIME}`)===FEED_BLOB,'feed blob drift');assert(sh(`git hash-object ${CARD_RUNTIME}`)===CARD_BLOB,'card blob drift');assert(sh('git status --porcelain')==='','dirty checkpoint');const p=parse(fs.readFileSync(TARGET,'utf8'));assert(p.declarations.length===147&&p.dead.length===4,`parent parse ${p.declarations.length}/${p.dead.length}`);assert(p.dead.map(d=>d.line).join(',')==='120,121,142,143','dead lines drift');assert(new Set(p.dead.map(d=>d.selector)).size===2,'family count drift');assert(p.dead.every(d=>d.context.includes('@media (max-width: 560px)')),'context drift');assert(p.dead[0].winnerLine===270&&p.dead[1].winnerLine===271&&p.dead[2].winnerLine===341&&p.dead[3].winnerLine===340,'winner line drift');console.log('R2 PARENT PASS|decl=147|dead=4|families=2|identical=3|changed=1|context=max560|targetBlob='+TARGET_BLOB);return p}
function writeFixture(){fs.writeFileSync(FIXTURE,`<!doctype html><html class="home-index-root"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/${IMPORTER}"><style>html,body{margin:0}body{min-height:100vh}.featured-services{display:block;padding:12px}.service-card{display:block;width:min(100%,320px);box-sizing:border-box}.service-card__body{box-sizing:border-box}.service-card__profile{display:flex;align-items:center}.service-card__avatar{display:block;background:#ddd}.service-card__tags span{display:inline-block}</style></head><body class="home-index-shell"><main><section class="featured-services"><article class="service-card service-card--featured service-card--feed" data-ux052-fixture="true"><div class="service-card__body"><div class="service-card__rating">★ 4,9</div><div class="service-card__meta-row"><div class="service-card__profile"><span class="service-card__avatar" data-ux052-avatar></span><span class="service-card__location">Belo Horizonte, MG</span></div></div><div class="service-card__tags" data-ux052-tags><span>Teste</span><span>Casa</span><span>Extra</span></div><div class="service-card__footer"><strong class="service-card__price">R$ 120</strong><a class="service-card__cta" href="#">Ver anúncio</a></div></div></article></section></main></body></html>`) }
function removeDead(p){const src=fs.readFileSync(TARGET,'utf8'),nl=/\r?\n$/.test(src),lines=src.split(/\r?\n/);if(nl&&lines.at(-1)==='')lines.pop();for(const d of [...p.dead].sort((a,b)=>b.line-a.line)){assert(lines[d.line-1]?.trim().startsWith(`${d.property}:`),`source mismatch ${d.line}`);lines.splice(d.line-1,1)}fs.writeFileSync(TARGET,lines.join('\n')+(nl?'\n':''));const q=parse(fs.readFileSync(TARGET,'utf8')),stat=sh(`git diff --numstat -- ${TARGET}`).split(/\s+/);assert(q.declarations.length===143&&q.dead.length===0,`candidate parse ${q.declarations.length}/${q.dead.length}`);assert(stat[0]==='0'&&stat[1]==='4'&&stat[2]===TARGET,`diff drift ${stat.join(' ')}`);console.log('R2 REMOVE PASS|decl=147->143|dead=4->0|families=2|additions=0|deletions=4')}
async function capture(browser,tag){const out={};let overflow=0;for(const width of VIEWPORTS){const ctx=await browser.newContext({viewport:{width,height:900},reducedMotion:'reduce'}),page=await ctx.newPage();await page.route('**/*',route=>{const u=new URL(route.request().url());if(u.origin!=='http://127.0.0.1:4173')return route.abort();return route.continue()});await page.goto(`http://127.0.0.1:4173/${FIXTURE}?${tag}-${width}`,{waitUntil:'networkidle',timeout:20000});const s=await page.evaluate(({width,AVATAR_SEL,TAGS_SEL})=>{const card=document.querySelector('[data-ux052-fixture]'),avatar=document.querySelector(AVATAR_SEL),tags=document.querySelector(TAGS_SEL);if(!card||!avatar||!tags)throw new Error('fixture family missing');const ca=getComputedStyle(avatar),ct=getComputedStyle(tags),ar=avatar.getBoundingClientRect(),tr=tags.getBoundingClientRect(),cr=card.getBoundingClientRect(),round=n=>Math.round(n*1000)/1000;return{width,families:[document.querySelectorAll(AVATAR_SEL).length,document.querySelectorAll(TAGS_SEL).length],avatar:{width:ca.width,height:ca.height,rect:[round(ar.x),round(ar.y),round(ar.width),round(ar.height)]},tags:{margin:ct.margin,overflow:ct.overflow,rect:[round(tr.x),round(tr.y),round(tr.width),round(tr.height)]},card:[round(cr.x),round(cr.y),round(cr.width),round(cr.height)],doc:[document.documentElement.clientWidth,document.documentElement.scrollWidth,document.body.scrollWidth]};},{width,AVATAR_SEL,TAGS_SEL});assert(s.families[0]===1&&s.families[1]===1,`family reach ${width}: ${s.families}`);if(s.doc[1]>s.doc[0]+1||s.doc[2]>s.doc[0]+1)overflow++;out[String(width)]=s;await ctx.close()}console.log(`R2 FIXTURE CAPTURE|tag=${tag}|viewports=${VIEWPORTS.join(',')}|samples=${VIEWPORTS.length}|families=2/2|overflowSamples=${overflow}`);return{out,overflow}}
(async()=>{assert(SHA&&TARGET_BLOB&&IMPORTER_BLOB&&PAGE_BLOB&&FEED_BLOB&&CARD_BLOB,'missing env');const p=guard();writeFixture();const server=cp.spawn('python3',['-m','http.server','4173','--bind','127.0.0.1'],{stdio:'ignore'});try{await new Promise(r=>setTimeout(r,700));const browser=await chromium.launch({headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});try{const before=await capture(browser,'before');removeDead(p);const after=await capture(browser,'after');assert(JSON.stringify(before.out)===JSON.stringify(after.out),'fixture computed/layout parity mismatch');assert(before.overflow===after.overflow,`fixture overflow parity ${before.overflow}/${after.overflow}`);console.log(`R2 FIXTURE PASS|families=2/2|viewports=${VIEWPORTS.length}|before=${VIEWPORTS.length}|after=${VIEWPORTS.length}|runtimeDiffs=0|overflowParity=${before.overflow}->${after.overflow}|boundaries=389/390/391+559/560/561|importChain=home-runtime-feed`)}finally{await browser.close()}}finally{server.kill('SIGTERM')}sh(`git reset --hard ${SHA}`);sh('git clean -fdx');assert(sh('git rev-parse HEAD')===SHA&&sh(`git hash-object ${TARGET}`)===TARGET_BLOB&&sh('git status --porcelain')==='','restore drift');console.log(`R2 CHECKPOINT PASS|sha=${SHA}|productMutation=0|issueCreated=0|prCreated=0`)})().catch(e=>{console.error(e.stack||e);process.exit(1)});
